problems.solution:
Each thread writes exactly four bytes, and no two threads write the same ones — so no locks and no race conditions:

```cuda
#include <cstdio>
#include <cuda_runtime.h>
#include "tt_render.h"

#define W 256
#define H 256

__global__ void gradient(unsigned char *out, int w, int h) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    if (x >= w || y >= h) return;

    int idx = (y * w + x) * 4;
    out[idx + 0] = (unsigned char)x;    // red  grows left to right
    out[idx + 1] = (unsigned char)y;    // green grows top to bottom
    out[idx + 2] = 128;                 // constant blue
    out[idx + 3] = 255;                 // opaque
}

int main() {
    const size_t bytes = (size_t)W * H * 4;
    unsigned char *dPixels;
    cudaMalloc(&dPixels, bytes);
    unsigned char *hPixels = (unsigned char *)malloc(bytes);

    dim3 block(16, 16);
    dim3 grid((W + block.x - 1) / block.x, (H + block.y - 1) / block.y);
    gradient<<<grid, block>>>(dPixels, W, H);
    cudaMemcpy(hPixels, dPixels, bytes, cudaMemcpyDeviceToHost);

    tt_render_frame(hPixels, W, H);

    int a = 0, b = ((H - 1) * W + (W - 1)) * 4;
    printf("pixel(0,0) = %d %d %d %d\n", hPixels[a], hPixels[a+1], hPixels[a+2], hPixels[a+3]);
    printf("pixel(255,255) = %d %d %d %d\n", hPixels[b], hPixels[b+1], hPixels[b+2], hPixels[b+3]);

    cudaFree(dPixels);
    free(hPixels);
    return 0;
}
```

**Why this scales.** The image is 65,536 pixels, so the launch creates 65,536 threads across 256 blocks of 256. The GPU schedules them across its SMs however it likes; because every thread touches a disjoint slice of `out`, the order genuinely does not matter. That independence is what makes a problem a good fit for a GPU.

**Try changing it.** Swap the red and blue lines. Replace `x` with `x ^ y` for an XOR pattern. Each edit is one line, and the Render tab updates on the next run.

