problems.solution:
The whole problem is four lines inside a `while`:

```cuda
#include <cstdio>
#include <cmath>
#include <cuda_runtime.h>
#include "tt_render.h"

#define W        900
#define H        600
#define MAX_ITER 300

// How many steps before z escapes? Returns MAX_ITER if it never does.
__host__ __device__ int escapeCount(double cr, double ci, int maxIter) {
    double zr = 0.0, zi = 0.0;
    int i = 0;
    while (zr * zr + zi * zi <= 4.0 && i < maxIter) {
        double t = zr * zr - zi * zi + cr;
        zi = 2.0 * zr * zi + ci;
        zr = t;
        i++;
    }
    return i;
}

__global__ void render(unsigned char *out, int w, int h, int maxIter) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    if (x >= w || y >= h) return;

    double cr = -2.2 + (x / (double)w) * 3.0;
    double ci = -1.2 + (y / (double)h) * 2.4;
    int i = escapeCount(cr, ci, maxIter);

    int idx = (y * w + x) * 4;
    if (i >= maxIter) {
        out[idx] = out[idx + 1] = out[idx + 2] = 0;
    } else {
        float t = sqrtf((float)i / maxIter);
        out[idx + 0] = (unsigned char)(255.0f * (0.55f + 0.45f * cosf(6.2831853f * (3.0f * t + 0.85f))));
        out[idx + 1] = (unsigned char)(255.0f * (0.55f + 0.45f * cosf(6.2831853f * (3.0f * t + 0.95f))));
        out[idx + 2] = (unsigned char)(255.0f * (0.55f + 0.45f * cosf(6.2831853f * (3.0f * t + 0.15f))));
    }
    out[idx + 3] = 255;
}

static void report(double cr, double ci) {
    int i = escapeCount(cr, ci, MAX_ITER);
    printf("c=%.3f%+.3fi %s\n", cr, ci, i >= MAX_ITER ? "inside" : "outside");
}

int main() {
    const size_t bytes = (size_t)W * H * 4;
    unsigned char *dPixels;
    cudaMalloc(&dPixels, bytes);
    unsigned char *hPixels = (unsigned char *)malloc(bytes);

    dim3 block(16, 16);
    dim3 grid((W + block.x - 1) / block.x, (H + block.y - 1) / block.y);
    render<<<grid, block>>>(dPixels, W, H, MAX_ITER);
    cudaMemcpy(hPixels, dPixels, bytes, cudaMemcpyDeviceToHost);
    tt_render_frame(hPixels, W, H);

    report(0.0, 0.0);
    report(-1.0, 0.0);
    report(0.5, 0.5);
    report(2.0, 0.0);

    cudaFree(dPixels);
    free(hPixels);
    return 0;
}
```

**The temporary matters.** `zr` appears in both new components, so overwriting it before computing `zi` silently renders the wrong fractal. The `double t` holds the new real part until the old one has been used.

**Why `__host__ __device__`.** Marking `escapeCount` with both lets the *same* function compile for the GPU (for the image) and for the CPU (for the four printed checks). No duplicated maths — so the check genuinely tests the code that drew the picture.

**Thread divergence.** Neighbouring pixels can need wildly different iteration counts, but threads run in lockstep groups of 32 (a *warp*), and a warp takes as long as its slowest member. That is why the black interior, where every pixel runs the full `maxIter`, is the expensive part of this image.

